import { nightDiscoveryView } from './supernatural-discovery.js';

export function supernaturalNotes(s,ui,offered=[],{readOnly=false}={}) {
  const v=nightDiscoveryView(s);if(!v.invitations.length&&!v.legacyKnown)return '';
  const {e,button,actionCards,date}=ui;
  return `<section class="panel" data-supernatural-notes><div class="eyebrow">MEETINGS YOU REMEMBER</div><h2>Invitations left in the night</h2><p class="small-copy">${e(v.rateText)}</p>${v.legacyKnown?`<p>${e(v.legacyKnown)}</p>`:''}${v.invitations.map(r=>`<article class="legacy-record"><span class="badge">${e(r.status==='deferred'?'Undecided invitation':r.status)}</span><h3>${e(r.personName)}</h3><p>${e(r.kind==='patron'?'The twilight traveler':'The moonwise ranger')} · last seen ${e(date(r.lastSeenDay))} ${r.hex?'at trail hex '+e(r.hex)+', ':''}near ${e(r.locationName)}.</p><p>${r.status==='deferred'?'You know whom you met and where. Their return is uncertain; no quest or transformation has been accepted.':'Your recorded decision remains part of this life.'}</p>${r.lastSearchDay!=null?`<p class="small-copy">Last search ${e(date(r.lastSearchDay))}: ${e({met:'the traveler was found',absent:'the place was empty',interrupted:'another actual encounter intervened'}[r.lastSearchResult]||'recorded')}.</p>`:''}${button('Show the remembered place','night-location',r.id,'ghost small')}${r.status==='deferred'&&!readOnly?actionCards([offered.find(a=>a.id===`curse_revisit_${r.kind}`)].filter(Boolean)):''}${r.status==='deferred'&&readOnly&&!r.returnReason?'<p class="small-copy">Return to the remembered place and open your surroundings to search after dark.</p>':''}${r.status==='deferred'&&!readOnly&&!r.returnReason&&!offered.some(a=>a.id===`curse_revisit_${r.kind}`)?'<p class="small-copy">Resolve the current decision before searching.</p>':''}${r.status==='deferred'&&r.returnReason?`<p class="small-copy">${e(r.returnReason)}</p>`:''}</article>`).join('')}${v.exposure?`<details><summary>Weeks lived on eligible routes</summary><p class="small-copy">Since ${e(date(v.exposure.recordedFromDay))}: ${v.exposure.eligibleDays} eligible days, ${v.exposure.checkedWeeks} weekly discovery checks. Earlier unrecorded exposure is not inferred.</p></details>`:''}</section>`;
}
